class Member{private final String name;public Member(String n){if(n==null||n.trim().isEmpty())throw new IllegalArgumentException();name=n;}public String getName(){return name;}}
interface MembershipPlan{String getName();int getMonths();double calculateFee();}class MonthlyPlan implements MembershipPlan{public String getName(){return "Monthly";}public int getMonths(){return 1;}public double calculateFee(){return 1000;}}class QuarterlyPlan implements MembershipPlan{public String getName(){return "Quarterly";}public int getMonths(){return 3;}public double calculateFee(){return 2700;}}class AnnualPlan implements MembershipPlan{public String getName(){return "Annual";}public int getMonths(){return 12;}public double calculateFee(){return 9000;}}
class Membership{enum Status{ACTIVE,FROZEN,EXPIRED}private final Member member;private final MembershipPlan plan;private final double fee;private Status status=Status.ACTIVE;public Membership(Member m,MembershipPlan p){if(m==null||p==null)throw new IllegalArgumentException();member=m;plan=p;fee=p.calculateFee();}public void freeze(){if(status==Status.EXPIRED)throw new IllegalStateException("Cannot freeze an Expired membership");if(status!=Status.ACTIVE)throw new IllegalStateException();status=Status.FROZEN;}public void unfreeze(){if(status==Status.EXPIRED)throw new IllegalStateException();if(status!=Status.FROZEN)throw new IllegalStateException();status=Status.ACTIVE;}public void expire(){status=Status.EXPIRED;}public boolean checkIn(){return status==Status.ACTIVE;}public double getFee(){return fee;}public Status getStatus(){return status;}public Member getMember(){return member;}public MembershipPlan getPlan(){return plan;}}
public class MembershipDesk{public static Membership buyMembership(Member m,MembershipPlan p){return new Membership(m,p);}}
